package com.bank.spark.model;

// A SQL query text plus the alias we intend to broadcast.
public class SqlQuery {
    private final String sql;
    private final String intendedBroadcastAlias;

    public SqlQuery(String sql, String intendedBroadcastAlias) {
        this.sql = sql;
        this.intendedBroadcastAlias = intendedBroadcastAlias;
    }

    public String getSql() { return sql; }
    public String getIntendedBroadcastAlias() { return intendedBroadcastAlias; }
}
