package com.bank.spark.service;

import com.bank.spark.model.SqlQuery;

import java.util.regex.Matcher;
import java.util.regex.Pattern;

// Detects a correctly placed BROADCAST hint and reports the resulting strategy.
public class HintInterpreter {

    // Matches /*+ BROADCAST(alias) */ (also BROADCASTJOIN / MAPJOIN) right after SELECT.
    private static final Pattern HINT = Pattern.compile(
            "(?is)\\bSELECT\\s*/\\*\\+\\s*(BROADCAST|BROADCASTJOIN|MAPJOIN)\\s*\\(([^)]*)\\)\\s*\\*/");

    public String interpret(SqlQuery q) {
        Matcher m = HINT.matcher(q.getSql());
        if (!m.find()) {
            return "No top-level broadcast hint found -> optimizer decides by threshold (likely SortMergeJoin)";
        }
        String keyword = m.group(1).toUpperCase();
        String aliases = m.group(2).replaceAll("\\s", "");
        boolean namesIntended = aliases.equals(q.getIntendedBroadcastAlias())
                || aliases.matches("(^|.*,)" + Pattern.quote(q.getIntendedBroadcastAlias()) + "(,.*|$)");
        if (namesIntended) {
            return keyword + " hint on '" + aliases + "' APPLIED -> BroadcastHashJoin (broadcast " + q.getIntendedBroadcastAlias() + ")";
        }
        return keyword + " hint names '" + aliases + "' but intended '" + q.getIntendedBroadcastAlias()
                + "' -> hint does not cover the intended table";
    }
}
