package com.bank.spark;

import com.bank.spark.model.SqlQuery;
import com.bank.spark.service.HintInterpreter;

import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class SqlHintDemo {

    private static final Logger log = Logger.getLogger(SqlHintDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        handler.setLevel(Level.ALL);
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        HintInterpreter interpreter = new HintInterpreter();

        // Case 1: correctly placed hint broadcasting customers (alias c).
        SqlQuery good = new SqlQuery(
                "SELECT /*+ BROADCAST(c) */ t.txn_id, c.name "
                        + "FROM transactions t JOIN customers c ON t.cust_id = c.id "
                        + "WHERE c.region = 'West'", "c");
        log.info("Case 1: " + interpreter.interpret(good));

        // Case 2: MAPJOIN synonym, same effect.
        SqlQuery synonym = new SqlQuery(
                "SELECT /*+ MAPJOIN(c) */ t.txn_id, c.name "
                        + "FROM transactions t JOIN customers c ON t.cust_id = c.id", "c");
        log.info("Case 2: " + interpreter.interpret(synonym));

        // Case 3: no hint at all.
        SqlQuery none = new SqlQuery(
                "SELECT t.txn_id, c.name FROM transactions t JOIN customers c ON t.cust_id = c.id", "c");
        log.warning("Case 3: " + interpreter.interpret(none));

        log.info("Verify with EXPLAIN that BroadcastExchange + BroadcastHashJoin appear on customers.");
    }
}

